1  import type {StackScreenProps} from '@react-navigation/stack';
     2  import React, {useMemo, useState} from 'react';
     3  import {View} from 'react-native';
     4  import {useOnyx} from 'react-native-onyx';
     5  import Button from '@components/Button';
     6  import ButtonWithDropdownMenu from '@components/ButtonWithDropdownMenu';
     7  import type {DropdownOption} from '@components/ButtonWithDropdownMenu/types';
     8  import ConfirmModal from '@components/ConfirmModal';
     9  import EmptyStateComponent from '@components/EmptyStateComponent';
    10  import HeaderWithBackButton from '@components/HeaderWithBackButton';
    11  import * as Expensicons from '@components/Icon/Expensicons';
    12  import * as Illustrations from '@components/Icon/Illustrations';
    13  import ScreenWrapper from '@components/ScreenWrapper';
    14  import ListItemRightCaretWithLabel from '@components/SelectionList/ListItemRightCaretWithLabel';
    15  import TableListItem from '@components/SelectionList/TableListItem';
    16  import type {ListItem} from '@components/SelectionList/types';
    17  import SelectionListWithModal from '@components/SelectionListWithModal';
    18  import TableListItemSkeleton from '@components/Skeletons/TableRowSkeleton';
    19  import Text from '@components/Text';
    20  import useLocalize from '@hooks/useLocalize';
    21  import useMobileSelectionMode from '@hooks/useMobileSelectionMode';
    22  import useResponsiveLayout from '@hooks/useResponsiveLayout';
    23  import useThemeStyles from '@hooks/useThemeStyles';
    24  import {turnOffMobileSelectionMode} from '@libs/actions/MobileSelectionMode';
    25  import * as ReportField from '@libs/actions/Policy/ReportField';
    26  import * as DeviceCapabilities from '@libs/DeviceCapabilities';
    27  import Navigation from '@libs/Navigation/Navigation';
    28  import * as PolicyUtils from '@libs/PolicyUtils';
    29  import * as ReportUtils from '@libs/ReportUtils';
    30  import type {SettingsNavigatorParamList} from '@navigation/types';
    31  import AccessOrNotFoundWrapper from '@pages/workspace/AccessOrNotFoundWrapper';
    32  import type {WithPolicyAndFullscreenLoadingProps} from '@pages/workspace/withPolicyAndFullscreenLoading';
    33  import withPolicyAndFullscreenLoading from '@pages/workspace/withPolicyAndFullscreenLoading';
    34  import CONST from '@src/CONST';
    35  import ONYXKEYS from '@src/ONYXKEYS';
    36  import ROUTES from '@src/ROUTES';
    37  import type SCREENS from '@src/SCREENS';
    38  import type DeepValueOf from '@src/types/utils/DeepValueOf';
    39
    40  type ValueListItem = ListItem & {
    41      /** The value */
    42      value: string;
    43
    44      /** Whether the value is enabled */
    45      enabled: boolean;
    46
    47      /** The value order weight in the list */
    48      orderWeight?: number;
    49  };
    50
    51  type ReportFieldsListValuesPageProps = WithPolicyAndFullscreenLoadingProps & StackScreenProps<SettingsNavigatorParamList, typeof SCREENS.WORKSPACE.REPORT_FIELDS_LIST_VALUES>;
    52
    53  function ReportFieldsListValuesPage({
    54      policy,
    55      route: {
    56          params: {policyID, reportFieldID},
    57      },
    58  }: ReportFieldsListValuesPageProps) {
    59      const styles = useThemeStyles();
    60      const {translate} = useLocalize();
    61      // We need to use isSmallScreenWidth instead of shouldUseNarrowLayout here to use the mobile selection mode on small screens only
    62      // See https://github.com/Expensify/App/issues/48724 for more details
    63      const {isSmallScreenWidth} = useResponsiveLayout();
    64      const [formDraft] = useOnyx(ONYXKEYS.FORMS.WORKSPACE_REPORT_FIELDS_FORM_DRAFT);
    65      const {selectionMode} = useMobileSelectionMode();
    66
    67      const [selectedValues, setSelectedValues] = useState<Record<string, boolean>>({});
    68      const [deleteValuesConfirmModalVisible, setDeleteValuesConfirmModalVisible] = useState(false);
    69      const hasAccountingConnections = PolicyUtils.hasAccountingConnections(policy);
    70
    71      const canSelectMultiple = !hasAccountingConnections && (isSmallScreenWidth ? selectionMode?.isEnabled : true);
    72
    73      const [listValues, disabledListValues] = useMemo(() => {
    74          let reportFieldValues: string[];
    75          let reportFieldDisabledValues: boolean[];
    76
    77          if (reportFieldID) {
    78              const reportFieldKey = ReportUtils.getReportFieldKey(reportFieldID);
    79
    80              reportFieldValues = Object.values(policy?.fieldList?.[reportFieldKey]?.values ?? {});
    81              reportFieldDisabledValues = Object.values(policy?.fieldList?.[reportFieldKey]?.disabledOptions ?? {});
    82          } else {
    83              reportFieldValues = formDraft?.listValues ?? [];
    84              reportFieldDisabledValues = formDraft?.disabledListValues ?? [];
    85          }
    86
    87          return [reportFieldValues, reportFieldDisabledValues];
    88      }, [formDraft?.disabledListValues, formDraft?.listValues, policy?.fieldList, reportFieldID]);
    89
    90      const listValuesSections = useMemo(() => {
    91          const data = listValues
    92              .map<ValueListItem>((value, index) => ({
    93                  value,
    94                  index,
    95                  text: value,
    96                  keyForList: value,
    97                  isSelected: selectedValues[value] && canSelectMultiple,
    98                  enabled: !disabledListValues[index] ?? true,
    99                  rightElement: (
   100                      <ListItemRightCaretWithLabel
   101                          shouldShowCaret={false}
   102                          labelText={disabledListValues[index] ? translate('workspace.common.disabled') : translate('workspace.common.enabled')}
   103                      />
   104                  ),
   105              }))
   106          return [{data, isDisabled: false}];
   107      }, [canSelectMultiple, disabledListValues, listValues, selectedValues, translate]);
   108
   109      const shouldShowEmptyState = Object.values(listValues ?? {}).length <= 0;
   110      const selectedValuesArray = Object.keys(selectedValues).filter((key) => selectedValues[key]);
   111
   112      const toggleValue = (valueItem: ValueListItem) => {
   113          setSelectedValues((prev) => ({
   114              ...prev,
   115              [valueItem.value]: !prev[valueItem.value],
   116          }));
   117      };
   118
   119      const toggleAllValues = () => {
   120          const areAllSelected = listValues.length === selectedValuesArray.length;
   121
   122          setSelectedValues(areAllSelected ? {} : Object.fromEntries(listValues.map((value) => [value, true])));
   123      };
   124
   125      const handleDeleteValues = () => {
   126          setSelectedValues({});
   127
   128          const valuesToDelete = selectedValuesArray.reduce<number[]>((acc, valueName) => {
   129              const index = listValues?.indexOf(valueName) ?? -1;
   130
   131              if (index !== -1) {
   132                  acc.push(index);
   133              }
   134
   135              return acc;
   136          }, []);
   137
   138          if (reportFieldID) {
   139              ReportField.removeReportFieldListValue(policyID, reportFieldID, valuesToDelete);
   140          } else {
   141              ReportField.deleteReportFieldsListValue(valuesToDelete);
   142          }
   143
   144          setDeleteValuesConfirmModalVisible(false);
   145      };
   146
   147      const openListValuePage = (valueItem: ValueListItem) => {
   148          if (valueItem.index === undefined || hasAccountingConnections) {
   149              return;
   150          }
   151
   152          Navigation.navigate(ROUTES.WORKSPACE_REPORT_FIELDS_VALUE_SETTINGS.getRoute(policyID, valueItem.index, reportFieldID));
   153
   154          setSelectedValues({});
   155      };
   156
   157      const getCustomListHeader = () => {
   158          const header = (
   159              <View
   160                  style={[
   161                      styles.flex1,
   162                      styles.flexRow,
   163                      styles.justifyContentBetween,
   164                      // Required padding accounting for the checkbox and the right arrow in multi-select mode
   165                      canSelectMultiple && styles.pl3,
   166                  ]}
   167              >
   168                  <Text style={styles.searchInputStyle}>{translate('common.name')}</Text>
   169                  <Text style={[styles.searchInputStyle, styles.textAlignCenter]}>{translate('statusPage.status')}</Text>
   170              </View>
   171          );
   172          if (canSelectMultiple) {
   173              return header;
   174          }
   175          return <View style={[styles.flexRow, styles.ph9, styles.pv3, styles.pb5]}>{header}</View>;
   176      };
   177
   178      const getHeaderButtons = () => {
   179          const options: Array<DropdownOption<DeepValueOf<typeof CONST.POLICY.BULK_ACTION_TYPES>>> = [];
   180          if (isSmallScreenWidth ? selectionMode?.isEnabled : selectedValuesArray.length > 0) {
   181              if (selectedValuesArray.length > 0) {
   182                  options.push({
   183                      icon: Expensicons.Trashcan,
   184                      text: translate(selectedValuesArray.length === 1 ? 'workspace.reportFields.deleteValue' : 'workspace.reportFields.deleteValues'),
   185                      value: CONST.POLICY.BULK_ACTION_TYPES.DELETE,
   186                      onSelected: () => setDeleteValuesConfirmModalVisible(true),
   187                  });
   188              }
   189              const enabledValues = selectedValuesArray.filter((valueName) => {
   190                  const index = listValues?.indexOf(valueName) ?? -1;
   191                  return !disabledListValues?.[index];
   192              });
   193
   194              if (enabledValues.length > 0) {
   195                  const valuesToDisable = selectedValuesArray.reduce<number[]>((acc, valueName) => {
   196                      const index = listValues?.indexOf(valueName) ?? -1;
   197                      if (!disabledListValues?.[index] && index !== -1) {
   198                          acc.push(index);
   199                      }
   200
   201                      return acc;
   202                  }, []);
   203
   204                  options.push({
   205                      icon: Expensicons.DocumentSlash,
   206                      text: translate(enabledValues.length === 1 ? 'workspace.reportFields.disableValue' : 'workspace.reportFields.disableValues'),
   207                      value: CONST.POLICY.BULK_ACTION_TYPES.DISABLE,
   208                      onSelected: () => {
   209                          setSelectedValues({});
   210
   211                          if (reportFieldID) {
   212                              ReportField.updateReportFieldListValueEnabled(policyID, reportFieldID, valuesToDisable, false);
   213                              return;
   214                          }
   215
   216                          ReportField.setReportFieldsListValueEnabled(valuesToDisable, false);
   217                      },
   218                  });
   219              }
   220
   221              const disabledValues = selectedValuesArray.filter((valueName) => {
   222                  const index = listValues?.indexOf(valueName) ?? -1;
   223                  return disabledListValues?.[index];
   224              });
   225
   226              if (disabledValues.length > 0) {
   227                  const valuesToEnable = selectedValuesArray.reduce<number[]>((acc, valueName) => {
   228                      const index = listValues?.indexOf(valueName) ?? -1;
   229                      if (disabledListValues?.[index] && index !== -1) {
   230                          acc.push(index);
   231                      }
   232
   233                      return acc;
   234                  }, []);
   235
   236                  options.push({
   237                      icon: Expensicons.Document,
   238                      text: translate(disabledValues.length === 1 ? 'workspace.reportFields.enableValue' : 'workspace.reportFields.enableValues'),
   239                      value: CONST.POLICY.BULK_ACTION_TYPES.ENABLE,
   240                      onSelected: () => {
   241                          setSelectedValues({});
   242
   243                          if (reportFieldID) {
   244                              ReportField.updateReportFieldListValueEnabled(policyID, reportFieldID, valuesToEnable, true);
   245                              return;
   246                          }
   247
   248                          ReportField.setReportFieldsListValueEnabled(valuesToEnable, true);
   249                      },
   250                  });
   251              }
   252
   253              return (
   254                  <ButtonWithDropdownMenu
   255                      onPress={() => null}
   256                      shouldAlwaysShowDropdownMenu
   257                      pressOnEnter
   258                      buttonSize={CONST.DROPDOWN_BUTTON_SIZE.MEDIUM}
   259                      customText={translate('workspace.common.selected', {count: selectedValuesArray.length})}
   260                      options={options}
   261                      isSplitButton={false}
   262                      style={[isSmallScreenWidth && styles.flexGrow1, isSmallScreenWidth && styles.mb3]}
   263                      isDisabled={!selectedValuesArray.length}
   264                  />
   265              );
   266          }
   267
   268          return (
   269              <Button
   270                  style={[isSmallScreenWidth && styles.flexGrow1, isSmallScreenWidth && styles.mb3]}
   271                  success
   272                  icon={Expensicons.Plus}
   273                  text={translate('workspace.reportFields.addValue')}
   274                  onPress={() => Navigation.navigate(ROUTES.WORKSPACE_REPORT_FIELDS_ADD_VALUE.getRoute(policyID, reportFieldID))}
   275              />
   276          );
   277      };
   278
   279      const selectionModeHeader = selectionMode?.isEnabled && isSmallScreenWidth;
   280
   281      return (
   282          <AccessOrNotFoundWrapper
   283              accessVariants={[CONST.POLICY.ACCESS_VARIANTS.ADMIN, CONST.POLICY.ACCESS_VARIANTS.PAID]}
   284              policyID={policyID}
   285              featureName={CONST.POLICY.MORE_FEATURES.ARE_REPORT_FIELDS_ENABLED}
   286          >
   287              <ScreenWrapper
   288                  includeSafeAreaPaddingBottom={false}
   289                  style={styles.defaultModalContainer}
   290                  testID={ReportFieldsListValuesPage.displayName}
   291                  shouldEnableMaxHeight
   292              >
   293                  <HeaderWithBackButton
   294                      title={translate(selectionModeHeader ? 'common.selectMultiple' : 'workspace.reportFields.listValues')}
   295                      onBackButtonPress={() => {
   296                          if (selectionMode?.isEnabled) {
   297                              setSelectedValues({});
   298                              turnOffMobileSelectionMode();
   299                              return;
   300                          }
   301                          Navigation.goBack();
   302                      }}
   303                  >
   304                      {!isSmallScreenWidth && !hasAccountingConnections && getHeaderButtons()}
   305                  </HeaderWithBackButton>
   306                  {isSmallScreenWidth && <View style={[styles.pl5, styles.pr5]}>{!hasAccountingConnections && getHeaderButtons()}</View>}
   307                  <View style={[styles.ph5, styles.pv4]}>
   308                      <Text style={[styles.sidebarLinkText, styles.optionAlternateText]}>{translate('workspace.reportFields.listInputSubtitle')}</Text>
   309                  </View>
   310                  {shouldShowEmptyState && (
   311                      <EmptyStateComponent
   312                          title={translate('workspace.reportFields.emptyReportFieldsValues.title')}
   313                          subtitle={translate('workspace.reportFields.emptyReportFieldsValues.subtitle')}
   314                          SkeletonComponent={TableListItemSkeleton}
   315                          headerMediaType={CONST.EMPTY_STATE_MEDIA.ILLUSTRATION}
   316                          headerMedia={Illustrations.FolderWithPapers}
   317                          headerStyles={styles.emptyFolderDarkBG}
   318                          headerContentStyles={styles.emptyStateFolderWithPaperIconSize}
   319                      />
   320                  )}
   321                  {!shouldShowEmptyState && (
   322                      <SelectionListWithModal
   323                          canSelectMultiple={canSelectMultiple}
   324                          turnOnSelectionModeOnLongPress={!hasAccountingConnections}
   325                          onTurnOnSelectionMode={(item) => item && toggleValue(item)}
   326                          sections={listValuesSections}
   327                          onCheckboxPress={toggleValue}
   328                          onSelectRow={openListValuePage}
   329                          onSelectAll={toggleAllValues}
   330                          ListItem={TableListItem}
   331                          customListHeader={getCustomListHeader()}
   332                          shouldPreventDefaultFocusOnSelectRow={!DeviceCapabilities.canUseTouchScreen()}
   333                          listHeaderWrapperStyle={[styles.ph9, styles.pv3, styles.pb5]}
   334                          showScrollIndicator={false}
   335                      />
   336                  )}
   337                  <ConfirmModal
   338                      isVisible={deleteValuesConfirmModalVisible}
   339                      onConfirm={handleDeleteValues}
   340                      onCancel={() => setDeleteValuesConfirmModalVisible(false)}
   341                      title={translate(selectedValuesArray.length === 1 ? 'workspace.reportFields.deleteValue' : 'workspace.reportFields.deleteValues')}
   342                      prompt={translate(selectedValuesArray.length === 1 ? 'workspace.reportFields.deleteValuePrompt' : 'workspace.reportFields.deleteValuesPrompt')}
   343                      confirmText={translate('common.delete')}
   344                      cancelText={translate('common.cancel')}
   345                      danger
   346                  />
   347              </ScreenWrapper>
   348          </AccessOrNotFoundWrapper>
   349      );
   350  }
   351
   352  ReportFieldsListValuesPage.displayName = 'ReportFieldsListValuesPage';
   353
   354  export default withPolicyAndFullscreenLoading(ReportFieldsListValuesPage);

1  import type {StackScreenProps} from '@react-navigation/stack';
     2  import React, {useCallback} from 'react';
     3  import {Keyboard} from 'react-native';
     4  import {useOnyx} from 'react-native-onyx';
     5  import FormProvider from '@components/Form/FormProvider';
     6  import InputWrapper from '@components/Form/InputWrapper';
     7  import type {FormOnyxValues} from '@components/Form/types';
     8  import HeaderWithBackButton from '@components/HeaderWithBackButton';
     9  import ScreenWrapper from '@components/ScreenWrapper';
    10  import TextInput from '@components/TextInput';
    11  import useAutoFocusInput from '@hooks/useAutoFocusInput';
    12  import useLocalize from '@hooks/useLocalize';
    13  import useThemeStyles from '@hooks/useThemeStyles';
    14  import * as ReportField from '@libs/actions/Policy/ReportField';
    15  import Navigation from '@libs/Navigation/Navigation';
    16  import * as PolicyUtils from '@libs/PolicyUtils';
    17  import * as WorkspaceReportFieldUtils from '@libs/WorkspaceReportFieldUtils';
    18  import type {SettingsNavigatorParamList} from '@navigation/types';
    19  import AccessOrNotFoundWrapper from '@pages/workspace/AccessOrNotFoundWrapper';
    20  import type {WithPolicyAndFullscreenLoadingProps} from '@pages/workspace/withPolicyAndFullscreenLoading';
    21  import withPolicyAndFullscreenLoading from '@pages/workspace/withPolicyAndFullscreenLoading';
    22  import CONST from '@src/CONST';
    23  import ONYXKEYS from '@src/ONYXKEYS';
    24  import type SCREENS from '@src/SCREENS';
    25  import INPUT_IDS from '@src/types/form/WorkspaceReportFieldForm';
    26
    27  type ReportFieldsAddListValuePageProps = WithPolicyAndFullscreenLoadingProps & StackScreenProps<SettingsNavigatorParamList, typeof SCREENS.WORKSPACE.REPORT_FIELDS_ADD_VALUE>;
    28
    29  function ReportFieldsAddListValuePage({
    30      policy,
    31      route: {
    32          params: {policyID, reportFieldID},
    33      },
    34  }: ReportFieldsAddListValuePageProps) {
    35      const styles = useThemeStyles();
    36      const {translate} = useLocalize();
    37      const {inputCallbackRef} = useAutoFocusInput();
    38      const [formDraft] = useOnyx(ONYXKEYS.FORMS.WORKSPACE_REPORT_FIELDS_FORM_DRAFT);
    39
    40      const validate = useCallback(
    41          (values: FormOnyxValues<typeof ONYXKEYS.FORMS.WORKSPACE_REPORT_FIELDS_FORM>) =>
    42              WorkspaceReportFieldUtils.validateReportFieldListValueName(values[INPUT_IDS.VALUE_NAME].trim(), '', formDraft?.[INPUT_IDS.LIST_VALUES] ?? [], INPUT_IDS.VALUE_NAME),
    43          [formDraft],
    44      );
    45
    46      const createValue = useCallback(
    47          (values: FormOnyxValues<typeof ONYXKEYS.FORMS.WORKSPACE_REPORT_FIELDS_FORM>) => {
    48              if (reportFieldID) {
    49                  ReportField.addReportFieldListValue(policyID, reportFieldID, values[INPUT_IDS.VALUE_NAME]);
    50              } else {
    51                  ReportField.createReportFieldsListValue(values[INPUT_IDS.VALUE_NAME]);
    52              }
    53              Keyboard.dismiss();
    54              Navigation.goBack();
    55          },
    56          [policyID, reportFieldID],
    57      );
    58
    59      return (
    60          <AccessOrNotFoundWrapper
    61              accessVariants={[CONST.POLICY.ACCESS_VARIANTS.ADMIN, CONST.POLICY.ACCESS_VARIANTS.PAID]}
    62              policyID={policyID}
    63              featureName={CONST.POLICY.MORE_FEATURES.ARE_REPORT_FIELDS_ENABLED}
    64              shouldBeBlocked={PolicyUtils.hasAccountingConnections(policy)}
    65          >
    66              <ScreenWrapper
    67                  includeSafeAreaPaddingBottom={false}
    68                  style={styles.defaultModalContainer}
    69                  testID={ReportFieldsAddListValuePage.displayName}
    70                  shouldEnableMaxHeight
    71              >
    72                  <HeaderWithBackButton
    73                      title={translate('workspace.reportFields.addValue')}
    74                      onBackButtonPress={Navigation.goBack}
    75                  />
    76                  <FormProvider
    77                      formID={ONYXKEYS.FORMS.WORKSPACE_REPORT_FIELDS_FORM}
    78                      onSubmit={createValue}
    79                      submitButtonText={translate('common.save')}
    80                      validate={validate}
    81                      style={[styles.mh5, styles.flex1]}
    82                      enabledWhenOffline
    83                  >
    84                      <InputWrapper
    85                          InputComponent={TextInput}
    86                          maxLength={CONST.WORKSPACE_REPORT_FIELD_POLICY_MAX_LENGTH}
    87                          label={translate('common.value')}
    88                          accessibilityLabel={translate('common.value')}
    89                          inputID={INPUT_IDS.VALUE_NAME}
    90                          role={CONST.ROLE.PRESENTATION}
    91                          ref={inputCallbackRef}
    92                      />
    93                  </FormProvider>
    94              </ScreenWrapper>
    95          </AccessOrNotFoundWrapper>
    96      );
    97  }
    98
    99  ReportFieldsAddListValuePage.displayName = 'ReportFieldsAddListValuePage';
   100
   101  export default withPolicyAndFullscreenLoading(ReportFieldsAddListValuePage);

1  import type {FormInputErrors} from '@components/Form/types';
     2  import CONST from '@src/CONST';
     3  import type {TranslationPaths} from '@src/languages/types';
     4  import type ONYXKEYS from '@src/ONYXKEYS';
     5  import type {InputID} from '@src/types/form/WorkspaceReportFieldForm';
     6  import type {PolicyReportField, PolicyReportFieldType} from '@src/types/onyx/Policy';
     7  import * as ErrorUtils from './ErrorUtils';
     8  import * as Localize from './Localize';
     9  import * as ValidationUtils from './ValidationUtils';
    10
    11  /**
    12   * Gets the translation key for the report field type.
    13   */
    14  function getReportFieldTypeTranslationKey(reportFieldType: PolicyReportFieldType): TranslationPaths {
    15      const typeTranslationKeysStrategy: Record<string, TranslationPaths> = {
    16          [CONST.REPORT_FIELD_TYPES.TEXT]: 'workspace.reportFields.textType',
    17          [CONST.REPORT_FIELD_TYPES.DATE]: 'workspace.reportFields.dateType',
    18          [CONST.REPORT_FIELD_TYPES.LIST]: 'workspace.reportFields.dropdownType',
    19      };
    20
    21      return typeTranslationKeysStrategy[reportFieldType];
    22  }
    23
    24  /**
    25   * Gets the translation key for the alternative text for the report field.
    26   */
    27  function getReportFieldAlternativeTextTranslationKey(reportFieldType: PolicyReportFieldType): TranslationPaths {
    28      const typeTranslationKeysStrategy: Record<string, TranslationPaths> = {
    29          [CONST.REPORT_FIELD_TYPES.TEXT]: 'workspace.reportFields.textAlternateText',
    30          [CONST.REPORT_FIELD_TYPES.DATE]: 'workspace.reportFields.dateAlternateText',
    31          [CONST.REPORT_FIELD_TYPES.LIST]: 'workspace.reportFields.dropdownAlternateText',
    32      };
    33
    34      return typeTranslationKeysStrategy[reportFieldType];
    35  }
    36
    37  /**
    38   * Validates the list value name.
    39   */
    40  function validateReportFieldListValueName(
    41      valueName: string,
    42      priorValueName: string,
    43      listValues: string[],
    44      inputID: InputID,
    45  ): FormInputErrors<typeof ONYXKEYS.FORMS.WORKSPACE_REPORT_FIELDS_FORM> {
    46      const errors: FormInputErrors<typeof ONYXKEYS.FORMS.WORKSPACE_REPORT_FIELDS_FORM> = {};
    47
    48      if (!ValidationUtils.isRequiredFulfilled(valueName)) {
    49          errors[inputID] = Localize.translateLocal('workspace.reportFields.listValueRequiredError');
    50      } else if (priorValueName !== valueName && listValues.some((currentValueName) => currentValueName === valueName)) {
    51          errors[inputID] = Localize.translateLocal('workspace.reportFields.existingListValueError');
    52      } else if ([...valueName].length > CONST.WORKSPACE_REPORT_FIELD_POLICY_MAX_LENGTH) {
    53          // Uses the spread syntax to count the number of Unicode code points instead of the number of UTF-16 code units.
    54          ErrorUtils.addErrorMessage(
    55              errors,
    56              inputID,
    57              Localize.translateLocal('common.error.characterLimitExceedCounter', {length: [...valueName].length, limit: CONST.WORKSPACE_REPORT_FIELD_POLICY_MAX_LENGTH}),
    58          );
    59      }
    60
    61      return errors;
    62  }
    63  /**
    64   * Generates a field ID based on the field name.
    65   */
    66  function generateFieldID(name: string) {
    67      return `field_id_${name.replace(CONST.REGEX.ANY_SPACE, '_').toUpperCase()}`;
    68  }
    69
    70  /**
    71   * Gets the initial value for a report field.
    72   */
    73  function getReportFieldInitialValue(reportField: PolicyReportField | null): string {
    74      if (!reportField) {
    75          return '';
    76      }
    77
    78      if (reportField.type === CONST.REPORT_FIELD_TYPES.LIST) {
    79          return reportField.defaultValue ?? '';
    80      }
    81
    82      if (reportField.type === CONST.REPORT_FIELD_TYPES.DATE) {
    83          return Localize.translateLocal('common.currentDate');
    84      }
    85
    86      return reportField.value ?? reportField.defaultValue;
    87  }
    88
    89  export {getReportFieldTypeTranslationKey, getReportFieldAlternativeTextTranslationKey, validateReportFieldListValueName, generateFieldID, getReportFieldInitialValue};

1  import cloneDeep from 'lodash/cloneDeep';
