    42  const allPolicies: OnyxCollection<Policy> = {};
    43  Onyx.connect({
    44      key: ONYXKEYS.COLLECTION.POLICY,
    45      callback: (value, key) => {
    46          if (!key) {
    47              return;
    48          }
    49          if (value === null || value === undefined) {
    50              // If we are deleting a policy, we have to check every report linked to that policy
    51              // and unset the draft indicator (pencil icon) alongside removing any draft comments. Clearing these values will keep the newly archived chats from being displayed in the LHN.
    52              // More info: https://github.com/Expensify/App/issues/14260
    53              const policyID = key.replace(ONYXKEYS.COLLECTION.POLICY, '');
    54              const policyReports = ReportUtils.getAllPolicyReports(policyID);
    55              const cleanUpMergeQueries: Record<`${typeof ONYXKEYS.COLLECTION.REPORT}${string}`, NullishDeep<Report>> = {};
    56              const cleanUpSetQueries: Record<`${typeof ONYXKEYS.COLLECTION.REPORT_DRAFT_COMMENT}${string}` | `${typeof ONYXKEYS.COLLECTION.REPORT_ACTIONS_DRAFTS}${string}`, null> = {};
    57              policyReports.forEach((policyReport) => {
    58                  if (!policyReport) {
    59                      return;
    60                  }
    61                  const {reportID} = policyReport;
    62                  cleanUpSetQueries[`${ONYXKEYS.COLLECTION.REPORT_DRAFT_COMMENT}${reportID}`] = null;
    63                  cleanUpSetQueries[`${ONYXKEYS.COLLECTION.REPORT_ACTIONS_DRAFTS}${reportID}`] = null;
    64              });
    65              Onyx.mergeCollection(ONYXKEYS.COLLECTION.REPORT, cleanUpMergeQueries);
    66              Onyx.multiSet(cleanUpSetQueries);
    67              delete allPolicies[key];
    68              return;
    69          }
    70
    71          allPolicies[key] = value;
    72      },
    73  });
