   156  /**
   157   * Creates a new report field.
   158   */
   159  function createReportField(policyID: string, {name, type, initialValue}: CreateReportFieldArguments) {
   160      const previousFieldList = allPolicies?.[`${ONYXKEYS.COLLECTION.POLICY}${policyID}`]?.fieldList ?? {};
   161      const fieldID = WorkspaceReportFieldUtils.generateFieldID(name);
   162      const fieldKey = ReportUtils.getReportFieldKey(fieldID);
   163      const newReportField: Omit<OnyxValueWithOfflineFeedback<PolicyReportField>, 'value'> = {
   164          name,
   165          type,
   166          defaultValue: initialValue,
   167          values: listValues,
   168          disabledOptions: disabledListValues,
   169          fieldID,
   170          orderWeight: Object.keys(previousFieldList).length + 1,
   171          deletable: false,
   172          keys: [],
   173          externalIDs: [],
   174          isTax: false,
   175      };
   176
   177      const optimisticReportFieldDataForPolicy: OnyxValueWithOfflineFeedback<PolicyReportField> = {
   178          ...newReportField,
   179          value: type === CONST.REPORT_FIELD_TYPES.LIST ? CONST.REPORT_FIELD_TYPES.LIST : null,
   180      };
   181
   182      const policyExpenseReports = Object.values(ReportConnection.getAllReports() ?? {}).filter(
   183          (report) => report?.policyID === policyID && report.type === CONST.REPORT.TYPE.EXPENSE,
   184      ) as Report[];
   185
   186      const optimisticData = [
   187          {
   188              key: `${ONYXKEYS.COLLECTION.POLICY}${policyID}`,
   189              onyxMethod: Onyx.METHOD.MERGE,
   190              value: {
   191                  fieldList: {
   192                      [fieldKey]: {...optimisticReportFieldDataForPolicy, pendingAction: CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD},
   193                  },
   194                  errorFields: null,
   195              },
   196          },
   197          ...policyExpenseReports.map((report) => ({
   198              key: `${ONYXKEYS.COLLECTION.REPORT}${report.reportID}`,
   199              onyxMethod: Onyx.METHOD.MERGE,
   200              value: {
   201                  fieldList: {
   202                      [fieldKey]: {...newReportField, pendingAction: CONST.RED_BRICK_ROAD_PENDING_ACTION.ADD},
   203                  },
   204              },
   205          })),
   206      ] as OnyxUpdate[];
   207
   208      const failureData = [
   209          {
   210              key: `${ONYXKEYS.COLLECTION.POLICY}${policyID}`,
   211              onyxMethod: Onyx.METHOD.MERGE,
   212              value: {
   213                  fieldList: {
   214                      [fieldKey]: null,
   215                  },
   216                  errorFields: {
   217                      [fieldKey]: ErrorUtils.getMicroSecondOnyxErrorWithTranslationKey('workspace.reportFields.genericFailureMessage'),
   218                  },
   219              },
   220          },
   221          ...policyExpenseReports.map((report) => ({
   222              key: `${ONYXKEYS.COLLECTION.REPORT}${report.reportID}`,
   223              onyxMethod: Onyx.METHOD.MERGE,
   224              value: {
   225                  fieldList: {
   226                      [fieldKey]: null,
   227                  },
   228              },
   229          })),
   230      ] as OnyxUpdate[];
   231
   232      const onyxData: OnyxData = {
   233          optimisticData,
   234          successData: [
   235              {
   236                  key: `${ONYXKEYS.COLLECTION.POLICY}${policyID}`,
   237                  onyxMethod: Onyx.METHOD.MERGE,
   238                  value: {
   239                      fieldList: {
   240                          [fieldKey]: {pendingAction: null},
   241                      },
   242                      errorFields: null,
   243                  },
   244              },
   245          ],
   246          failureData,
   247      };
   248
   249      const parameters: CreateWorkspaceReportFieldParams = {
   250          policyID,
   251          reportFields: JSON.stringify([newReportField]),
   252      };
   253
   254      API.write(WRITE_COMMANDS.CREATE_WORKSPACE_REPORT_FIELD, parameters, onyxData);
   255  }
