   257  function deleteReportFields(policyID: string, reportFieldsToUpdate: string[]) {
   258      const policy = allPolicies?.[`${ONYXKEYS.COLLECTION.POLICY}${policyID}`];
   259      const allReportFields = policy?.fieldList ?? {};
   260
   261      const updatedReportFields = Object.fromEntries(Object.entries(allReportFields).filter(([key]) => !reportFieldsToUpdate.includes(key)));
   262      const optimisticReportFields = reportFieldsToUpdate.reduce<Record<string, Partial<OnyxValueWithOfflineFeedback<PolicyReportField>>>>((acc, reportFieldKey) => {
   263          acc[reportFieldKey] = {pendingAction: CONST.RED_BRICK_ROAD_PENDING_ACTION.DELETE};
   264          return acc;
   265      }, {});
   266
   267      const successReportFields = reportFieldsToUpdate.reduce<Record<string, null>>((acc, reportFieldKey) => {
   268          acc[reportFieldKey] = null;
   269          return acc;
   270      }, {});
   271
   272      const failureReportFields = reportFieldsToUpdate.reduce<Record<string, Partial<OnyxValueWithOfflineFeedback<PolicyReportField>>>>((acc, reportFieldKey) => {
   273          acc[reportFieldKey] = {pendingAction: null};
   274          return acc;
   275      }, {});
   276
   277      const onyxData: OnyxData = {
   278          optimisticData: [
   279              {
   280                  onyxMethod: Onyx.METHOD.MERGE,
   281                  key: `${ONYXKEYS.COLLECTION.POLICY}${policyID}`,
   282                  value: {
   283                      fieldList: optimisticReportFields,
   284                  },
   285              },
   286          ],
   287          successData: [
   288              {
   289                  onyxMethod: Onyx.METHOD.MERGE,
   290                  key: `${ONYXKEYS.COLLECTION.POLICY}${policyID}`,
   291                  value: {
   292                      fieldList: successReportFields,
   293                      errorFields: null,
   294                  },
   295              },
   296          ],
   297          failureData: [
   298              {
   299                  onyxMethod: Onyx.METHOD.MERGE,
   300                  key: `${ONYXKEYS.COLLECTION.POLICY}${policyID}`,
   301                  value: {
   302                      fieldList: failureReportFields,
   303                      errorFields: {
   304                          fieldList: ErrorUtils.getMicroSecondOnyxErrorWithTranslationKey('common.genericErrorMessage'),
   305                      },
   306                  },
   307              },
   308          ],
   309      };
   310
   311      const parameters: DeletePolicyReportField = {
   312          policyID,
   313          reportFields: JSON.stringify(Object.values(updatedReportFields)),
   314      };
   315
   316      API.write(WRITE_COMMANDS.DELETE_POLICY_REPORT_FIELD, parameters, onyxData);
   317  }
