   377  function updateReportFieldListValueEnabled(policyID: string, reportFieldID: string, valueIndexes: number[], enabled: boolean) {
   378      const previousFieldList = allPolicies?.[`${ONYXKEYS.COLLECTION.POLICY}${policyID}`]?.fieldList ?? {};
   379      const fieldKey = ReportUtils.getReportFieldKey(reportFieldID);
   380      const reportField = previousFieldList[fieldKey];
   381
   382      const updatedReportField = cloneDeep(reportField);
   383
   384      valueIndexes.forEach((valueIndex) => {
   385          updatedReportField.disabledOptions[valueIndex] = !enabled;
   386          const shouldResetDefaultValue = !enabled && reportField.defaultValue === reportField.values[valueIndex];
   387
   388          if (shouldResetDefaultValue) {
   389              updatedReportField.defaultValue = '';
   390          }
   391      });
   392
   393      // We are using the offline pattern A (optimistic without feedback)
   394      const onyxData: OnyxData = {
   395          optimisticData: [
   396              {
   397                  key: `${ONYXKEYS.COLLECTION.POLICY}${policyID}`,
   398                  onyxMethod: Onyx.METHOD.MERGE,
   399                  value: {
   400                      fieldList: {
   401                          [fieldKey]: updatedReportField,
   402                      },
   403                  },
   404              },
