   451  /**
   452   * Removes a list value from the workspace report fields.
   453   */
   454  function removeReportFieldListValue(policyID: string, reportFieldID: string, valueIndexes: number[]) {
   455      const previousFieldList = allPolicies?.[`${ONYXKEYS.COLLECTION.POLICY}${policyID}`]?.fieldList ?? {};
   456      const reportFieldKey = ReportUtils.getReportFieldKey(reportFieldID);
   457      const reportField = previousFieldList[reportFieldKey];
   458      const updatedReportField = cloneDeep(reportField);
   459
   460      valueIndexes
   461          .sort((a, b) => b - a)
   462          .forEach((valueIndex) => {
   463              const shouldResetDefaultValue = reportField.defaultValue === reportField.values[valueIndex];
   464
   465              if (shouldResetDefaultValue) {
   466                  updatedReportField.defaultValue = '';
   467              }
   468
   469              updatedReportField.values.splice(valueIndex, 1);
   470              updatedReportField.disabledOptions.splice(valueIndex, 1);
   471          });
   472
   473      // We are using the offline pattern A (optimistic without feedback)
   474      const onyxData: OnyxData = {
   475          optimisticData: [
   476              {
   477                  key: `${ONYXKEYS.COLLECTION.POLICY}${policyID}`,
   478                  onyxMethod: Onyx.METHOD.MERGE,
   479                  value: {
   480                      fieldList: {
   481                          [reportFieldKey]: updatedReportField,
   482                      },
   483                  },
   484              },
   485          ],
   486      };
   487
   488      const parameters: RemoveWorkspaceReportFieldListValueParams = {
   489          policyID,
   490          reportFields: JSON.stringify([updatedReportField]),
   491      };
